  check(FollowUp.subject("¿Cuándo nació Tomás Rivel?").equals(Arrays.asList("tomas","rivel"))&&FollowUp.complete("¿Y dónde murió?","tomas rivel").equals("dónde murió tomas rivel")&&FollowUp.complete("donde murio lucio maren","tomas rivel").equals("donde murio lucio maren")&&FollowUp.complete("y donde murio","").equals("donde murio"),"subject is borrowed only when missing: "+FollowUp.complete("¿Y dónde murió?","tomas rivel"));
  CreatorPersistenceCheck.Fake c=new CreatorPersistenceCheck.Fake();final NotebookDisk disk=NotebookDisk.of(c);String filler=" Este texto agrega contenido suficiente para que el documento tenga varias oraciones útiles y distintas entre sí.";
  disk.put("Tomás Rivel",new StringReader("Tomás Rivel fue un ingeniero ficticio de Quirema. Tomás Rivel nació el 3 de mayo de 1851 en Altamisa. Estudió en la escuela de puentes de Belorado. Murió en 1923 en Tindal. El puente mide 120 metros de largo."+filler),"https://example.com/rivel","web");
  check(FollowUp.resolve(c,"¿Y dónde murió?").equals("dónde murió?"),"nothing to borrow before any answer");FollowUp.remember(c,"cuando nacio tomas rivel",null);check(FollowUp.resolve(c,"¿Y dónde murió?").equals("dónde murió tomas rivel"),"follow-up completed: "+FollowUp.resolve(c,"¿Y dónde murió?"));
  Lector.Found follow=Lector.read(m,disk.selected(FollowUp.resolve(c,"¿Y dónde murió?")),FollowUp.resolve(c,"¿Y dónde murió?"));check(follow!=null&&follow.sentence.contains("Tindal"),"the completed follow-up is answered: "+(follow==null?null:follow.sentence));
  FollowUp.remember(c,"donde murio",null);check(FollowUp.resolve(c,"y cuando nacio").contains("rivel"),"a follow-up keeps the borrowed subject");FollowUp.forget(c);check(FollowUp.resolve(c,"y cuando nacio").equals("cuando nacio"),"forgotten with the library");
  // Short answers cut out of the chosen sentence
